/**
Check if the provided target URL string is within the provided domain.
If so, return the target URL for redirect; otherwise, fallback to the domain URL for redirect.
Use https protocol.

Examples:

	getTargetForRedirect("https://music.example.com", "example.com") -> "https://music.example.com"
	getTargetForRedirect("https://example.com/service", "example.com") -> "https://example.com/service"
	getTargetForRedirect("https://blog.example.com/posts", "example.com") -> "https://blog.example.com/posts"
	getTargetForRedirect("https://another.com", "example.com") -> "https://example.com"

@param target: The target URL string.
@param domain: The domain string, without protocol.

@return The URL string for redirect.
*/
func getTargetForRedirect(target string, domain string) string {
	// --- Step 1: Validate and sanitize the 'domain' parameter for both comparison and fallback ---
	// This is crucial to prevent open redirects via the 'domain' parameter itself.

	// Prepend a scheme to the 'domain' string to allow url.Parse to correctly extract the host.
	// This handles cases where 'domain' might contain paths or query parameters.
	tempDomainURL, err := url.Parse("https://" + domain)
	if err != nil || tempDomainURL.Host == "" {
		// If 'domain' is malformed or empty, it's unusable.
		// Return a truly safe, hardcoded default URL.
		// This prevents "https://" or "https://malicious/path" from being returned.
		return "https://default-safe-domain.com" // Replace with your actual safe default
	}

	// Extract the hostname from the parsed domain, stripping any port.
	cleanDomainHost := tempDomainURL.Hostname()

	// Validate this clean host using PSL for comparison purposes.
	domainParsed, err := publicsuffix.Parse(cleanDomainHost)
	if err != nil {
		// If cleanDomainHost cannot be parsed by PSL (e.g., IP address, malformed),
		// it's not a valid base for secure redirection comparison.
		// Return a truly safe default.
		return "https://default-safe-domain.com" // Replace with your actual safe default
	}
	registrableDomain := domainParsed.RegistrableDomain

	// If registrableDomain is empty, it means the input 'domain' was a public suffix itself (e.g., "com", "co.uk")
	// or an invalid domain that PSL couldn't resolve to a registrable part.
	// This is a critical check to prevent TLD/Public Suffix Bypass.
	if registrableDomain == "" {
		// Return a truly safe default.
		return "https://default-safe-domain.com" // Replace with your actual safe default
	}

	// Now, construct the fallback URL using the *validated and sanitized* cleanDomainHost.
	// This ensures no paths/queries from the original 'domain' parameter are included.
	fallbackURL := "https://" + cleanDomainHost

	// --- Step 2: Parse and validate the target URL ---
	parsedTarget, err := url.Parse(target)
	if err != nil {
		// If the target URL is invalid or cannot be parsed, fall back to the validated domain URL.
		return fallbackURL
	}

	// If the parsed URL has no host (e.g., a relative path or malformed URL),
	// it cannot be considered within the specified domain.
	if parsedTarget.Host == "" {
		return fallbackURL
	}

	// Extract the hostname from the parsed target URL, stripping any port number.
	targetHost := parsedTarget.Hostname()

	// --- Step 3: Validate and parse the 'targetHost' using Public Suffix List (PSL) ---
	targetHostParsed, err := publicsuffix.Parse(targetHost)
	if err != nil {
		// If the targetHost cannot be parsed by PSL (e.g., malformed, or an IP address),
		// it's not a valid host for secure redirection. Return the fallback URL.
		return fallbackURL
	}
	registrableTargetDomain := targetHostParsed.RegistrableDomain

	// If registrableTargetDomain is empty, it means the targetHost was a public suffix itself
	// or an invalid host that PSL couldn't resolve.
	if registrableTargetDomain == "" {
		return fallbackURL
	}

	// --- Step 4: Secure comparison using registrable domains ---
	// Check if the registrable domains match. This is the robust and secure validation using PSL.
	isWithinDomain := registrableTargetDomain == registrableDomain

	if isWithinDomain {
		// If the target URL is within the domain, ensure it uses the HTTPS protocol.
		parsedTarget.Scheme = "https"
		// Return the (potentially modified to HTTPS) target URL.
		return parsedTarget.String()
	}

	// If the target URL is not within the specified domain, fall back to the validated domain URL.
	return fallbackURL
}

