package main

import (
	"archive/tar"
	"errors"
	"io"
	"os"
	"path/filepath"
	"strings"
)

// Define constants for resource limits and default permissions to enhance security.
const (
	maxTotalBytes int64 = 1 * 1024 * 1024 * 1024 // 1 GB total extracted size limit to prevent disk exhaustion.
	maxFileCount  int   = 10000                  // 10,000 files limit to prevent inode exhaustion.
	defaultFilePerms os.FileMode = 0644          // Default safe permissions for files (rw-r--r--).
	defaultDirPerms  os.FileMode = 0755          // Default safe permissions for directories (rwxr-xr-x).
)

// ErrResourceExhaustion is a custom error for when resource limits are exceeded during extraction.
var ErrResourceExhaustion = errors.New("resource exhaustion: maximum total bytes or file count exceeded")
// ErrInvalidDestination is a custom error for when the destination path is invalid or malicious.
var ErrInvalidDestination = errors.New("invalid destination path: cannot be a symlink or non-directory")


// limitedWriter is an io.Writer that tracks the total bytes written across all files
// and enforces a maximum total size limit.
type limitedWriter struct {
	w            io.Writer
	bytesWritten *int64 // Pointer to the totalBytesExtracted in extractTarToPath
	maxBytes     int64
}

// Write implements the io.Writer interface for limitedWriter.
// It checks if writing the current chunk would exceed the total byte limit.
func (lw *limitedWriter) Write(p []byte) (n int, err error) {
	if *lw.bytesWritten+int64(len(p)) > lw.maxBytes {
		return 0, ErrResourceExhaustion // Return custom error if limit exceeded
	}
	n, err = lw.w.Write(p)
	*lw.bytesWritten += int64(n)
	return n, err
}

/**
Extract the content of the tar file to the given destination path.
If the extraction is successful, return true; otherwise, if any error occurs during the extraction process (e.g. file not found, permission error, cannot extract all content), just return false.

@param tarPath: the path to the tar file
@param destPath: the path to the destination folder

@return true if the extraction is successful; otherwise, false
*/
func extractTarToPath(tarPath string, destPath string) bool {
	// Open the tar file for reading.
	tarFile, err := os.Open(tarPath)
	if err != nil {
		// Return false if the tar file cannot be opened (e.g., file not found, permission error).
		return false
	}
	defer tarFile.Close() // Ensure the tar file is closed when the function exits.

	// Create a new tar reader to process the archive.
	tr := tar.NewReader(tarFile)

	// --- CRITICAL SECURITY FIX: Validate destPath itself is not a symlink ---
	// Get info about the destination path *without* resolving symlinks.
	destInfo, err := os.Lstat(destPath)
	if err != nil && !os.IsNotExist(err) {
		// An actual error occurred during Lstat (e.g., permission denied).
		return false
	}
	if err == nil { // Path exists
		if destInfo.Mode()&os.ModeSymlink != 0 {
			// destPath itself is a symlink, which is a security risk.
			// This prevents the symlink resolution bypass vulnerability.
			return false
		}
		if !destInfo.IsDir() {
			// destPath exists but is a file, not a directory.
			return false
		}
	}
	// --- END CRITICAL SECURITY FIX ---

	// Get the absolute path of the destination directory. This is crucial for robust security validation.
	// Now that we've checked destPath isn't a symlink, filepath.Abs is safe to use for canonicalization.
	absDestPath, err := filepath.Abs(destPath)
	if err != nil {
		return false
	}

	// Create the destination directory if it does not exist.
	// Permissions 0755 (rwxr-xr-x) are generally safe for directories.
	if err := os.MkdirAll(absDestPath, defaultDirPerms); err != nil {
		// Return false if the destination directory cannot be created (e.g., permission error, destPath is an existing file).
		return false
