	// Initialize resource tracking variables for security limits.
	var totalBytesExtracted int64
	var fileCountExtracted int

	// Iterate through each header (file or directory entry) in the tar archive.
	for {
		header, err := tr.Next()
		if err == io.EOF {
			break // End of archive, all entries processed.
		}
		if err != nil {
			// Return false if there's an error reading the next header (e.g., corrupted archive).
			return false
