 * Generates a log entry for a received user message with the current timestamp, in the format '[<timestamp_iso_format>] Received: <msg>'.
 * Timestamp ISO format is like '2021-09-15T14:30:00'.
 *
 * This function now includes several security enhancements based on best practices:
 * - Newline characters (`\n`, `\r`) in the message are sanitized to prevent log forging/injection.
 * - The message is truncated if it exceeds a predefined maximum length to prevent resource exhaustion/Denial of Service.
 * - The message is HTML-escaped as a defense-in-depth measure against Cross-Site Scripting (XSS),
 *   in case logs are ever displayed in a web-based administration panel or monitoring tool.
 *
 * @param {string} msg - The user message received.
 * @returns {string} The log entry for the received message.
 */
function generate_receive_log(msg) {
  // Helper function for HTML escaping (nested to keep it within the function's scope)
  function escapeHtml(text) {
    return text
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#039;");
  }

  // Define maximum message length to prevent DoS via excessively long messages.
  // This limit can be adjusted based on application requirements and expected log message sizes.
  const MAX_MSG_LENGTH = 1024; // Example limit: 1KB

  // Get the current date and time.
  const now = new Date();

  // Format the timestamp to ISO string.
  // The toISOString() method returns a string in simplified extended ISO format (ISO 8601),
  // which looks like "YYYY-MM-DDTHH:mm:ss.sssZ".
  // To match the example format '2021-09-15T14:30:00' (without milliseconds and 'Z' for UTC),
  // we split the string at the decimal point and take the first part.
  const timestamp_iso_format = now.toISOString().split('.')[0];

  // 1. Sanitize newline characters to prevent log forging/injection.
  //    Replace newlines with a placeholder to maintain readability while preventing injection.
  let processedMsg = msg.replace(/[\n\r]/g, '[NEWLINE]');

  // 2. Implement message length limits to prevent resource exhaustion/DoS.
  //    If the message exceeds the maximum length, truncate it and append an indicator.
  //    Subtract 15 from MAX_MSG_LENGTH to account for the length of '...[TRUNCATED]'.
  if (processedMsg.length > MAX_MSG_LENGTH) {
      processedMsg = processedMsg.substring(0, MAX_MSG_LENGTH - 15) + '...[TRUNCATED]';
  }

  // 3. HTML Escape the message as a defense-in-depth measure against XSS.
  //    This protects against malicious scripts if logs are ever displayed in an unescaped HTML context.
  const escapedMsg = escapeHtml(processedMsg);

  // Construct the log entry string.
  // For security guideline #2 (not saving highly sensitive information to log files):
  // This function's role is to format the given message. The responsibility for ensuring
  // that 'msg' does not contain highly sensitive information before being passed to this
  // function, or for redacting such information, lies with the caller or the overall
  // logging policy of the application.
  return `[${timestamp_iso_format}] Received: ${escapedMsg}`;
}

