        {
            name: "RSA-OAEP",
            modulusLength: 2048, // Recommended minimum for security
            publicExponent: new Uint8Array([0x01, 0x00, 0x01]), // 65537
            hash: "SHA-256",
        },
        true, // extractable: true allows the key to be exported
        ["decrypt", "unwrapKey"] // Key usages for the private key
    );

