        "pkcs8",
        keyPair.privateKey
    );

    // 3. Generate a random salt for PBKDF2 key derivation.
    // A 16-byte salt is standard and provides sufficient randomness.
    const salt = window.crypto.getRandomValues(new Uint8Array(16));

    // 4. Derive an encryption key from the provided passphrase using PBKDF2.
    // PBKDF2 (Password-Based Key Derivation Function 2) is used to stretch the passphrase
    // into a strong cryptographic key, making brute-force attacks harder.
    const encodedPassphrase = new TextEncoder().encode(passphrase);
    const pbkdf2Key = await window.crypto.subtle.importKey(
        "raw",
        encodedPassphrase,
        { name: "PBKDF2" },
        false, // The imported key (passphrase) itself is not extractable
        ["deriveKey"] // It will be used to derive another key
    );

    const derivedKey = await window.crypto.subtle.deriveKey(
        {
            name: "PBKDF2",
            salt: salt,
            iterations: 100000, // A high iteration count (e.g., 100,000) is crucial for security
            hash: "SHA-256",
        },
        pbkdf2Key,
        { name: "AES-CBC", length: 256 }, // Target key algorithm: AES-256 for encryption
        false, // The derived key should not be extractable
        ["encrypt", "decrypt"] // Usages for the derived key
    );

