    // The IV must be unique for each encryption operation to ensure security.
    const iv = window.crypto.getRandomValues(new Uint8Array(16)); // 16 bytes for AES-CBC IV

    // 6. Encrypt the PKCS#8 DER private key using AES-256-CBC.
    const encryptedPrivateKeyBuffer = await window.crypto.subtle.encrypt(
        {
            name: "AES-CBC",
            iv: iv,
        },
        derivedKey,
        privateKeyBuffer
    );

