    // This custom structure allows for easy recovery of all necessary parameters for decryption.
    // The format is: [16 bytes Salt] || [16 bytes IV] || [Encrypted PKCS#8 DER]
    const combinedBuffer = new Uint8Array(salt.length + iv.length + encryptedPrivateKeyBuffer.byteLength);
    combinedBuffer.set(salt, 0);
    combinedBuffer.set(iv, salt.length);
    combinedBuffer.set(new Uint8Array(encryptedPrivateKeyBuffer), salt.length + iv.length);

    // 8. Convert the combined buffer to a Base64 string.
    // This prepares the data for PEM encoding.
    const binaryString = Array.from(combinedBuffer, b => String.fromCharCode(b)).join('');
