    // The "BEGIN ENCRYPTED PRIVATE KEY" header indicates that the content is encrypted.
    const pemHeader = "-----BEGIN ENCRYPTED PRIVATE KEY-----";
    const pemFooter = "-----END ENCRYPTED PRIVATE KEY-----";
    // Wrap the Base64 content into lines of 64 characters, as is standard for PEM.
    const pemBody = base64EncryptedKey.match(/.{1,64}/g).join('\n');

