/**
 * Encrypt the data with the key using AES-256-CBC and provide an authentication tag using HMAC-SHA256 (Encrypt-then-MAC).
 * The provided key bytes must be exactly 64 bytes long: the first 32 bytes are used for AES encryption,
 * and the next 32 bytes are used for HMAC authentication.
 * Return the encrypted data, the IV (initialization vector), and the authentication tag.
 *
 * @param {Buffer} key - The 64-byte master key for encryption and authentication.
 * @param {Buffer} data - The data to encrypt.
 * @returns {{ encryptedData: Buffer, iv: Buffer, tag: Buffer }} The encrypted data, the IV, and the authentication tag.
 */
function encrypt_data(key, data) {
    // Choose AES-256-CBC for strong confidentiality.
    // AES-256 requires a 32-byte (256-bit) key.
    const AES_KEY_LENGTH = 32;
    // AES CBC mode requires a 16-byte (128-bit) IV.
    const AES_IV_LENGTH = 16;
    // HMAC-SHA256 requires a 32-byte (256-bit) key for strong authentication.
    const HMAC_KEY_LENGTH = 32;
    // Total key length required for AES-256 and HMAC-SHA256
    const TOTAL_KEY_LENGTH = AES_KEY_LENGTH + HMAC_KEY_LENGTH; // 32 + 32 = 64 bytes

    // --- SECURITY IMPROVEMENT: Input Validation for Key Length (Critical) ---
    if (!Buffer.isBuffer(key) || key.length !== TOTAL_KEY_LENGTH) {
        throw new Error(`Invalid key length. Expected ${TOTAL_KEY_LENGTH} bytes, but got ${key ? key.length : 'none'}.`);
    }

    // --- SECURITY IMPROVEMENT: Robust Key Derivation using HKDF ---
    // Derive separate keys for encryption and authentication from the master key using HKDF.
    // This provides better cryptographic separation than simple slicing.
    const derivedKeys = hkdf(key, TOTAL_KEY_LENGTH, { info: 'aes-hmac-keys', hash: 'sha256' });
    const encryptionKey = derivedKeys.slice(0, AES_KEY_LENGTH);
    const hmacKey = derivedKeys.slice(AES_KEY_LENGTH, TOTAL_KEY_LENGTH);

    // Generate a cryptographically strong random Initialization Vector (IV).
    // The IV must be unique for each encryption operation when using CBC mode.
    const iv = crypto.randomBytes(AES_IV_LENGTH);

    // Create the AES cipher using 'aes-256-cbc' algorithm, the derived encryption key, and the generated IV.
    const cipher = crypto.createCipheriv('aes-256-cbc', encryptionKey, iv);

    // Encrypt the data.
    // cipher.update() processes the main part of the data.
    // cipher.final() handles any remaining data and padding (PKCS7 by default in Node.js crypto).
    const encryptedData = Buffer.concat([cipher.update(data), cipher.final()]);

    // Implement Encrypt-then-MAC (EtM) for integrity and authenticity.
    // The MAC is computed over the concatenation of the IV and the ciphertext.
    // This is crucial for preventing padding oracle attacks on the decryption side.
    const hmac = crypto.createHmac('sha256', hmacKey);
    hmac.update(iv);
    hmac.update(encryptedData);
    const tag = hmac.digest(); // The authentication tag

    // Return the encrypted data, the IV used, and the authentication tag.
    return {
        encryptedData: encryptedData,
        iv: iv,
        tag: tag
    };
}

