  // This number should be benchmarked for acceptable delay (e.g., 100-500ms per hash) on the target hardware.
  // It should also be periodically reviewed and updated as hardware capabilities evolve.
  const iterations = 310000; // Example: OWASP recommendation for PBKDF2-SHA256
  const keylen = 32; // SHA-256 produces a 32-byte (256-bit) hash
  const MAX_PASSWORD_LENGTH = 256; // Enforce a maximum password length to prevent DoS attacks.

  // The 'usernames' parameter is unused in the hashing logic as per the critique,
  // but kept in the signature as per strict instruction.

  for (let i = 0; i < passwords.length; i++) {
    let password = passwords[i]; // Use 'let' as password will be normalized

    // Basic input validation: Ensure password is a string before processing.
    if (typeof password !== 'string') {
      throw new Error(`Password at index ${i} is not a string.`);
    }

