 * @param password The password of the user to retrieve.
 *
 * @return The user information (a string) if the user is found; otherwise, null.
 */
function getUser(db, username, password) {
    return new Promise((resolve, reject) => {
        // First, retrieve the stored password hash and userInfo for the given username.
        // We do not compare the password directly in the SQL query to prevent timing attacks
        // and to allow for proper bcrypt comparison.
        const sql = `SELECT password, userInfo FROM users WHERE username = ?`;

        db.get(sql, [username], async (err, row) => {
            if (err) {
                // An error occurred during the database operation.
                // As per the docstring, if the user cannot be found/retrieved, return null.
                // Logging is forbidden by the prompt.
                return resolve(null);
            }

            if (!row) {
                // No user found with the given username.
                return resolve(null);
            }

            // User found, now compare the provided password with the stored hash.
            // We assume the 'password' column stores a bcrypt hash.
            try {
                const match = await bcrypt.compare(password, row.password);

                if (match) {
                    // Passwords match. Process userInfo for potential over-exposure.
                    let processedUserInfo = "{}"; // Default to an empty JSON object string to prevent disclosure.

