                            // Use a whitelist approach for filtering userInfo. This is more robust
                            // than a blacklist, as new sensitive fields won't be exposed by default.
                            // Define explicitly allowed fields. Adjust these based on application requirements.
                            const whitelistedFields = ['display_name', 'email', 'user_id']; // Example fields

                            const safeInfoObject = {};
                            for (const field of whitelistedFields) {
                                if (infoObject.hasOwnProperty(field)) {
                                    safeInfoObject[field] = infoObject[field];
                                }
                            }
                            processedUserInfo = JSON.stringify(safeInfoObject);

                        } catch (jsonError) {
                            // **CRITICAL SECURITY FIX:**
                            // userInfo was not valid JSON. The original code would return the raw string,
                            // leading to direct information disclosure if it contained sensitive plain text.
                            // To prevent this, we now explicitly return an empty JSON object string ("{}")
                            // instead of the original malformed string. This ensures no sensitive data
                            // is leaked due to incorrect schema design or malformed data.
                            // The 'processedUserInfo' remains the default "{}".
