/**
 * @brief Helper function to parse a URL string and extract its scheme and host.
 *
 * This function attempts to parse the provided URL string, extracting the scheme
 * (e.g., "http", "https") and the host (e.g., "example.com", "sub.example.com").
 * It handles optional port numbers by stripping them from the host.
 * It also correctly parses IPv6 literal addresses and implicitly handles null bytes
 * by truncating parsed components at the first null byte encountered, which is
 * then used by the caller to reconstruct a safe URL.
 * Memory for the scheme and host strings is dynamically allocated and must be
 * freed by calling `free_parsed_url`.
 *
 * @param url_str The URL string to parse.
 * @param parsed_url A pointer to a ParsedUrl struct to store the results.
 *                   Its members will be set to NULL on failure.
 * @return true if parsing was successful and scheme/host were extracted, false otherwise.
 */
static bool parse_url(const char* url_str, ParsedUrl* parsed_url) {
    parsed_url->scheme = NULL;
    parsed_url->host = NULL;
    parsed_url->path_query_fragment_start = NULL;

    if (!url_str || *url_str == '\0') {
        return false;
    }

    // CRITICAL FIX 1: Null Byte Injection Prevention (Implicitly handled)
    // strstr, strncpy, and strlen naturally stop at the first null byte.
    // The critical vulnerability was copying the *original* target string later.
    // By reconstructing the URL *only* from parsed components (scheme, host),
    // any malicious data after an embedded null byte in the original `url_str`
    // will not be included in the redirect URL.

    const char* scheme_end = strstr(url_str, "://");
    if (!scheme_end) {
        return false; // No scheme separator "://" found
    }

    size_t scheme_len = scheme_end - url_str;
    if (scheme_len == 0) { // e.g., "://example.com" - malformed
        return false;
    }
    parsed_url->scheme = (char*)malloc(scheme_len + 1);
    if (!parsed_url->scheme) return false;
    strncpy(parsed_url->scheme, url_str, scheme_len);
    parsed_url->scheme[scheme_len] = '\0';

    const char* host_start = scheme_end + 3; // Skip "://"
    const char* host_part_end_boundary = host_start; // Marks the end of host+port part

