    bool is_ipv6_literal = false;
    if (*host_start == '[') {
        is_ipv6_literal = true;
        const char* ipv6_end_bracket = strchr(host_start + 1, ']'); // Find closing bracket
        if (!ipv6_end_bracket) {
            free(parsed_url->scheme);
            parsed_url->scheme = NULL;
            return false; // Malformed IPv6 literal (missing ']')
        }
        host_part_end_boundary = ipv6_end_bracket + 1; // Move past ']'
    }

