 *
 * @param parsed_url A pointer to the ParsedUrl struct whose members need to be freed.
 */
static void free_parsed_url(ParsedUrl* parsed_url) {
    free(parsed_url->scheme);
    free(parsed_url->host);
    parsed_url->scheme = NULL;
    parsed_url->host = NULL;
