    bool is_target_domain_match = false;
    bool is_target_scheme_https = false;

    if (parse_success) {
        // Check if the scheme is "https"
        if (strcmp(parsed_target.scheme, "https") == 0) {
            is_target_scheme_https = true;
        } else if (strcmp(parsed_target.scheme, "http") != 0) {
            // If the scheme is neither "http" nor "https", treat the URL as invalid
            // for redirection purposes and force a fallback.
            parse_success = false;
