            size_t domain_len = strlen(domain);
            size_t host_len = strlen(parsed_target.host);

            // CRITICAL FIX 3: Correct Subdomain Matching Logic
            // Revert the problematic `first_dot_in_host` check.
            // Implement the standard and correct subdomain check.
            if (strcmp(parsed_target.host, domain) == 0) {
                // Exact match (e.g., "example.com" matches "example.com")
                is_target_domain_match = true;
            } else if (host_len > domain_len &&
                       parsed_target.host[host_len - domain_len - 1] == '.' && // Check for '.' before domain
                       strcmp(parsed_target.host + host_len - domain_len, domain) == 0) {
