        // If the target URL's host is within the allowed domain,
        // ALWAYS return only the HTTPS scheme and the validated host.
        // Strip all path, query, and fragment components.
        size_t new_url_len = strlen(HTTPS_PREFIX) + strlen(parsed_target.host) + 1;
        result_url = (char*)malloc(new_url_len);
        if (result_url) {
            // Use snprintf for safe string formatting and buffer overflow prevention.
            snprintf(result_url, new_url_len, "%s%s", HTTPS_PREFIX, parsed_target.host);
        }
