            snprintf(result_url, fallback_len, "%s%s", HTTPS_PREFIX, domain);
        }
    }

    // Free memory allocated by the parse_url helper function
    if (parse_success) {
        free_parsed_url(&parsed_target);
    }

    return result_url;
