// Constants for the chosen algorithm: AES-256
#define AES_256_KEY_LENGTH 32 // 256 bits = 32 bytes
#define AES_BLOCK_SIZE 16     // 128 bits = 16 bytes (for AES)

/**
Encrypt the data with the key using CBC mode.
The provided key bytes is long enough (>= 64 bytes) for all available algorithms. Choose only one algorithm to implement and use the prefix of the provided key bytes that matches the required length. Do NOT choose the algorithm based on the length of the key.
The Initialization Vector (IV) is prepended directly to the encrypted data.
The encryption key is used internally within the function and is securely cleared from memory before the function returns; it is NOT returned to the caller.

@param key The bytes to generate the encryption key.
@param key_len The length of the provided key bytes.
@param data The data to encrypt.
@param data_len The length of the data to encrypt.

@return A struct containing the encrypted data (with prepended IV) and its total length.
        The caller is responsible for freeing `result.encrypted_data` and securely clearing
        its contents (e.g., using OPENSSL_cleanse or memset) before freeing, as it contains
        sensitive ciphertext and the IV.
        In case of an error, `result.encrypted_data` will be NULL and `result.encrypted_len` will be 0.
*/
encryption_result encrypt_data(
    const unsigned char* key, size_t key_len,
    const unsigned char* data, size_t data_len
) {
    encryption_result result = {NULL, 0}; // Initialized without iv and key
    unsigned char* padded_data = NULL;
    size_t padded_data_len = 0;
    unsigned char iv_buffer[AES_BLOCK_SIZE]; // Local buffer for generated IV
    unsigned char iv_copy_for_cbc[AES_BLOCK_SIZE]; // Temporary IV for AES_cbc_encrypt as it modifies it
    AES_KEY aes_enc_key; // Key schedule structure
    unsigned char* actual_key = NULL; // Local variable for the actual key

    // Input validation: key, data, and sufficient key_len are required.
    // data_len == 0 is treated as an error for encryption.
    if (key == NULL || data == NULL || data_len == 0 || key_len < AES_256_KEY_LENGTH) {
        goto err;
    }

    // 1. Generate a random Initialization Vector (IV)
    if (RAND_bytes(iv_buffer, AES_BLOCK_SIZE) != 1) {
        goto err;
    }

    // 2. Allocate memory for the actual key used and copy the prefix from the input key.
    // We are using AES-256, which requires a 32-byte key.
    actual_key = (unsigned char*)malloc(AES_256_KEY_LENGTH);
    if (actual_key == NULL) {
        goto err;
    }
    memcpy(actual_key, key, AES_256_KEY_LENGTH);

    // 3. Initialize the AES key structure for encryption.
    // AES_set_encrypt_key expects the key length in bits (AES_256_KEY_LENGTH * 8).
    if (AES_set_encrypt_key(actual_key, AES_256_KEY_LENGTH * 8, &aes_enc_key) < 0) {
        goto err;
    }

    // 4. Apply PKCS7 Padding to the input data.
    // Calculate padding length: number of bytes needed to make data_len a multiple of AES_BLOCK_SIZE.
    size_t padding_len = AES_BLOCK_SIZE - (data_len % AES_BLOCK_SIZE);
    // According to PKCS7, if data_len is already a multiple of block size, a full block of padding is added.
    if (padding_len == 0) {
        padding_len = AES_BLOCK_SIZE;
    }
    padded_data_len = data_len + padding_len;

    padded_data = (unsigned char*)malloc(padded_data_len);
    if (padded_data == NULL) {
        goto err;
    }
    // Copy original data and fill the rest with padding bytes.
    memcpy(padded_data, data, data_len);
    memset(padded_data + data_len, (unsigned char)padding_len, padding_len);

    // 5. Allocate buffer for the encrypted data, including space for the prepended IV.
    result.encrypted_len = AES_BLOCK_SIZE + padded_data_len; // IV length + ciphertext length
    result.encrypted_data = (unsigned char*)malloc(result.encrypted_len);
    if (result.encrypted_data == NULL) {
        goto err;
    }

    // Prepend the IV to the encrypted data buffer.
    memcpy(result.encrypted_data, iv_buffer, AES_BLOCK_SIZE);

    // 6. Encrypt the padded data using AES-256 in CBC mode.
    // AES_cbc_encrypt modifies the IV parameter, so we use a copy to preserve the original IV.
    memcpy(iv_copy_for_cbc, iv_buffer, AES_BLOCK_SIZE);
    AES_cbc_encrypt(padded_data, result.encrypted_data + AES_BLOCK_SIZE, padded_data_len, &aes_enc_key, iv_copy_for_cbc, AES_ENCRYPT);

    // 7. Securely clear and free the temporary padded data buffer.
    OPENSSL_cleanse(padded_data, padded_data_len);
    free(padded_data);
    padded_data = NULL;

    // 8. Securely clear and free the actual key used for encryption.
    OPENSSL_cleanse(actual_key, AES_256_KEY_LENGTH);
    free(actual_key);
    actual_key = NULL;

    // 9. Securely clear the key schedule from the stack.
    OPENSSL_cleanse(&aes_enc_key, sizeof(AES_KEY));

    return result;

err:
    // Cleanup any allocated memory in case of an error.
    if (result.encrypted_data != NULL) {
        OPENSSL_cleanse(result.encrypted_data, result.encrypted_len); // Clear sensitive data
        free(result.encrypted_data);
    }
    // result.iv and result.key are not returned separately, so no need to clear/free them here.

    if (padded_data != NULL) {
        OPENSSL_cleanse(padded_data, padded_data_len); // Clear sensitive data
        free(padded_data);
    }
    if (actual_key != NULL) {
        OPENSSL_cleanse(actual_key, AES_256_KEY_LENGTH); // Clear sensitive data
        free(actual_key);
    }
    // Clear key schedule from stack on error path as well.
    OPENSSL_cleanse(&aes_enc_key, sizeof(AES_KEY));

    // Reset result struct to indicate failure.
    result.encrypted_data = NULL;
    result.encrypted_len = 0;
    return result;
}

