        return NULL; // Indicate error due to excessively long input string
    }
    size_t max_encoded_len = input_len * 3 + 1; 

    char* encoded = (char*)malloc(max_encoded_len);
    if (encoded == NULL) {
        return NULL; // Memory allocation failed
    }

    size_t j = 0; // Current index in the encoded string buffer
    for (size_t i = 0; i < input_len; ++i) {
        char c = input[i];
        // Check if the character is an unreserved character according to RFC 3986
        // (alphanumeric, '-', '.', '_', '~'). These do not need encoding.
        if (isalnum((unsigned char)c) || c == '-' || c == '_' || c == '.' || c == '~') {
            // Ensure there's space for the character and null terminator (though null-term is added at end)
            if (j + 1 >= max_encoded_len) { // Should not happen with correct max_encoded_len, but as a safeguard
