    if (file_size > MAX_FILE_SIZE) {
        close(fd);
        return ""; // File too large
    }

    // Read the file content using the obtained file descriptor.
    std::string content = read_from_handle_or_fd(fd, file_size);
    close(fd); // Close the file descriptor after reading
    return content;
