// Helper function to normalize a path string (remove '.' and '..' components).
// This function does not resolve symlinks or check for path existence.
// It handles both absolute and relative paths.
static std::string normalize_path_string(const std::string& path) {
    if (path.empty()) {
        return "";
    }

    std::vector<std::string> components;
    std::string current_component;
    std::string::size_type start = 0;
    std::string::size_type end = path.find('/');

    bool is_absolute = (path[0] == '/');

    while (true) {
        if (end == std::string::npos) {
            current_component = path.substr(start);
        } else {
            current_component = path.substr(start, end - start);
        }

        if (current_component == "..") {
            if (is_absolute) {
                // For absolute paths, ".." means go up one level, but not above the root.
                // If components has more than just the root empty string, pop.
                if (components.size() > 1) {
                    components.pop_back();
                }
                // If components.size() == 1 (i.e., {""}), then "/.." stays at "/". Do nothing.
            } else { // Relative path
                if (!components.empty() && components.back() != "..") {
                    // Pop if not empty and the last component wasn't already ".."
                    components.pop_back();
                } else {
                    // If empty or last component was "..", push ".."
                    components.push_back("..");
                }
            }
        } else if (current_component != "." && !current_component.empty()) {
            components.push_back(current_component);
        }

        if (end == std::string::npos) {
            break;
        }
        start = end + 1;
        end = path.find('/', start);
    }

    std::string normalized_path;
    if (is_absolute) {
        normalized_path = "/";
    }

    // Reconstruct the path from components
    // Skip the initial empty string for absolute paths if it's the only component
    size_t start_idx = (is_absolute && !components.empty() && components[0].empty()) ? 1 : 0;

    for (size_t i = start_idx; i < components.size(); ++i) {
        if (i > start_idx || (is_absolute && start_idx == 0 && !normalized_path.empty() && normalized_path != "/")) {
            normalized_path += "/";
        }
        normalized_path += components[i];
    }

    if (normalized_path.empty()) {
        return is_absolute ? "/" : ".";
    }
    return normalized_path;
