// - It does NOT perform URL encoding or validation. Do NOT use its output directly in URL attributes (href, src, etc.).
// - It does NOT perform JavaScript escaping. Do NOT use its output directly within <script> blocks or event handlers.
// - It does NOT perform CSS escaping. Do NOT use its output directly within <style> blocks or style attributes.
// - For robust security in these other contexts, use dedicated context-specific escaping functions (e.g., url_encode, javascript_escape).
//
// This function escapes:
// - HTML special characters: &, <, >, ", '
// - All non-printable ASCII characters (bytes 0-31, 127) to numeric entities (&#NNN;).
// - All non-ASCII bytes (bytes > 127) to numeric entities (&#NNN;).
// This ensures maximum compatibility and prevents encoding-related issues or XSS in element content,
// regardless of the page's declared charset.
// This function is marked 'static' to give it internal linkage, meaning it's
// only visible within this translation unit, which is good practice for helper functions.
static std::string html_escape(const std::string& text) {
    std::string escaped_text;
    // Pre-allocate memory, estimating potential growth.
    // A character like '&' becomes "&amp;" (5 chars). A non-ASCII byte becomes "&#NNN;" (up to 6 chars).
    // A factor of 6 is a safe upper bound for single-byte characters.
    escaped_text.reserve(text.length() * 6);

    for (unsigned char c : text) { // Use unsigned char to correctly handle values > 127
        switch (c) {
            case '&':
                escaped_text.append("&amp;");
                break;
            case '<':
                escaped_text.append("&lt;");
                break;
            case '>':
                escaped_text.append("&gt;");
                break;
            case '"':
                escaped_text.append("&quot;");
                break;
            case '\'':
                // Use numeric entity for single quote (apostrophe) for broader compatibility
                escaped_text.append("&#39;");
                break;
            default:
                // Escape all non-printable ASCII characters (0-31), DEL (127), and all non-ASCII bytes (>127).
                // This ensures that only safe, printable ASCII characters (excluding the special HTML ones)
                // are passed through directly, preventing encoding issues and potential XSS vectors.
