// Helper function to create directories safely, preventing symlink following.
// This addresses "High Security Problem 3: Directory Symlink Following for `create_directories`".
void create_directories_symlink_safe(const std::filesystem::path& p) {
    if (p.empty()) {
        return;
    }

    std::filesystem::path current_path;
    for (const auto& component : p) {
        current_path /= component;

        // Skip root components (e.g., "/", "C:", "C:/") as they are assumed to exist and be valid.
        if (current_path == p.root_name() || current_path == p.root_directory()) {
            continue;
        }

        std::error_code ec;
        std::filesystem::file_status s = std::filesystem::symlink_status(current_path, ec);

        if (ec && ec.value() != ENOENT) { // ENOENT means it doesn't exist, which is fine. Other errors are problematic.
            throw std::runtime_error("Failed to check status of path component '" + current_path.string() + "': " + ec.message());
        }

        if (std::filesystem::exists(s)) {
            if (std::filesystem::is_directory(s)) {
                // It's a directory, continue to the next component
            } else if (std::filesystem::is_symlink(s)) {
                throw std::runtime_error("Path component '" + current_path.string() + "' is a symbolic link, which is not allowed.");
            } else {
                // It's a regular file or other non-directory type
                throw std::runtime_error("Path component '" + current_path.string() + "' exists but is not a directory.");
            }
        } else {
            // Directory does not exist, create it.
            // std::filesystem::create_directory (singular) does not follow symlinks for the *target* it creates.
            // It will fail if the parent is a symlink that points to an invalid location.
            if (!std::filesystem::create_directory(current_path, ec)) {
                // If it failed and it's not because it already exists (race condition), then throw.
                if (ec && ec.value() != EEXIST) {
                    throw std::runtime_error("Failed to create directory '" + current_path.string() + "': " + ec.message());
                }
            }
        }
    }
}

