    }

    // Remove the unnecessary cast from malloc's return value (Critique Point 4).
    // The implicit conversion from int to size_t for malloc is standard.
    char* buf = malloc(buf_size);

    // Security Guideline #5: Verify if the buffer is as large as specified.
    // Check if malloc failed to allocate memory.
    if (buf == NULL) {
        return NULL; // Memory allocation failed.
    }

    // Security Guideline #2: For functions such as fgets, ensure that the size value
    // for the operation is no greater than the amount of space available in the destination buffer.
    // fgets reads at most buf_size - 1 characters, ensuring null termination within bounds.
    // Security Guideline #6: Use vetted library (fgets is a safer alternative to gets).
    // Security Guideline #8: Truncate all input strings to a reasonable length
    // before passing them to copy and concatenation function (fgets handles this by limiting read length).
    if (fgets(buf, buf_size, stdin) == NULL) {
