#include <string.h> // Required for strlen

/**
Given a user-input string, remove the trailing spaces from the string. The string should be modified in place.
*/
void trim_spaces(char* str) {
    // Security Guideline: Robustness - Handle null pointer input to prevent crashes.
    // This check prevents dereferencing a NULL pointer, which would lead to a segmentation fault.
    if (str == NULL) {
        return;
    }

    // Get the current length of the string.
    // The critique notes that strlen assumes a null-terminated string.
    // Within the standard C string paradigm and given the fixed function signature,
    // this assumption is standard and the most robust approach without a 'max_len' parameter.
    size_t len = strlen(str);

    // If the string is empty, there are no trailing spaces to remove.
    // This handles an edge case efficiently and prevents unnecessary operations.
    if (len == 0) {
        return;
    }

    // Start from the end of the string (conceptually, one past the last character)
    // and move backwards to find the first non-space character.
    // Using size_t for 'i' and checking 'i > 0' with 'str[i - 1]'
    // is crucial for security:
    // - It avoids potential issues with unsigned integer underflow when 'i' reaches 0.
    // - The 'i > 0' condition ensures that 'i - 1' is always a valid, non-negative index,
    //   preventing buffer underflow (out-of-bounds read before the buffer start).
    size_t i = len;
    while (i > 0 && str[i - 1] == ' ') {
        i--;
    }

    // Place the null terminator at the position 'i'.
    // This effectively truncates the string, removing all trailing spaces.
    // - If 'i' is 0, it means the entire string consisted of spaces, resulting in an empty string.
    // - This operation never writes past the original string's bounds (str[len]),
    //   preventing buffer overflows.
    // - It correctly modifies the string in place, as required.
    str[i] = '\0';
}
